Path('models').mkdir(exist_ok=True)
z='((y-yc)/ys)';u='((x1-uc)/us)';v='((x2-vc)/vs)'
common_def='The state `y`, inputs `x1` and `x2`, and derivative `dy` have unspecified physical units; time is in s. No physical interpretation is assumed. '
norm_def='The fixed parameters `yc` and `ys` center and scale `y`; `uc` and `us` center and scale `x1`; `vc` and `vs` center and scale `x2`. Their ratios are dimensionless. '
normal=[('yc',1.3,'unknown','Center for `y`, chosen as a convenient round value near the training mean, not response-fitted.'),('ys',.3,'unknown','Scale for `y`, chosen as a convenient round spread from inspection of data/train.csv, not response-fitted.'),('uc',60.,'unknown','Center for `x1`, chosen as a convenient round value near the training mean, not response-fitted.'),('us',20.,'unknown','Scale for `x1`, chosen as a convenient round spread from inspection of data/train.csv, not response-fitted.'),('vc',18.,'unknown','Center for `x2`, chosen as a convenient round value near the training mean, not response-fitted.'),('vs',7.,'unknown','Scale for `x2`, chosen as a convenient round spread from inspection of data/train.csv, not response-fitted.')]
def fixed(name,val,unit,desc):return dict(name=name,value=val,unit=unit,type='fixed',description=desc)
def polynomial_terms():
 from sklearn.preprocessing import PolynomialFeatures
 powers=PolynomialFeatures(3).fit(np.zeros((1,3))).powers_
 return ['*'.join([t if n==1 else t+'**'+str(n) for t,n in zip([z,u,v],q) if n]) or '1' for q in powers]
cases={}
terms=polynomial_terms()
cases['Cubic']={'expression':' + '.join('p%d*%s'%(i,t) for i,t in enumerate(terms)),'descriptions':['Coefficient of `'+t+'`; controls this monomial contribution to `dy`.' for t in terms], 'fixed':normal,
 'family':'Continuous-time multivariate polynomial regression, total degree three, used as a nonlinear state equation. Prediction-error identification reference: L. Ljung, System Identification: Theory for the User, second edition, 1999; cited from memory, bibliographic source not checked.',
 'interpretation':common_def+norm_def+'The constant `p0` is a drift. Linear state feedback, input forcing, curvature, and input-dependent state feedback are represented by all monomials in the delivered expression. Each `p0` through `p19` multiplies the exact monomial stated in its parameter description. These are mathematical effects, not identified mechanisms. The highest pure-state term has a negative fitted coefficient, but global stability is not proved.',
 'origin':'The degree-three structure came from an explicit polynomial-library search, not physical reasoning. An affine fit was weak; bilinear feedback substantially improved simulation. Quadratic and cubic libraries then tested curvature and interactions. Degree four did not improve held-out simulation, and degree five had a training simulation failure; these were rejected. Orthogonal matching pursuit on degree-two through degree-four libraries was also tried by a helper, but its sparse derivative fits did not beat the full cubic derivative baseline. The full cubic was retained as the strongest smooth training-only derivative fit in validation simulation; no genetic programming or PySINDy was used.',
 'stage':'Ordinary least squares on all data/train.csv derivative rows using numpy.linalg.lstsq, with the twenty fixed monomials, estimated all coefficients simultaneously. It needs no starting values because the coefficients enter linearly. The resulting training-only derivative estimates are the numerical starting vector below. These are stored in explore_results.json under `cubic` with key `ols`; fit_explore.py reproduces them.',
 'limits':'Twenty coefficients are correlated because only two trajectories explore a restricted state-input region. Polynomial growth and RK4 instability are possible outside that region. The complete model is an empirical scalar approximation; positive local state slopes at a few observed points mean contraction is not guaranteed.'}
terms=['1',z,u,v,z+'*'+u,u+'**2',v+'**2','Max(y-kL,0)','Max(y-kM,0)','Max(y-kH,0)',u+'*Max(y-kL,0)',u+'*Max(y-kM,0)',u+'*Max(y-kH,0)']
cases['Hinge']={'expression':' + '.join('p%d*%s'%(i,t) for i,t in enumerate(terms)),'descriptions':['Coefficient of `'+t+'`; controls this basis contribution to `dy`.' for t in terms], 'fixed':normal+[('kL',1.1,'unknown','Lower state knot, fixed by inspecting the training state range, not optimized.'),('kM',1.4,'unknown','Middle state knot, fixed by inspecting the training state range, not optimized.'),('kH',1.7,'unknown','Upper state knot, fixed by inspecting the training state range, not optimized.')],
 'family':'Continuous piecewise-linear regression spline in the state with input interactions and quadratic input forcing. Related hinge-basis reference: J. H. Friedman, Multivariate Adaptive Regression Splines, Annals of Statistics, 1991; cited from memory, bibliographic source not checked. This fit does not use the adaptive MARS algorithm: its knots are fixed.',
 'interpretation':common_def+norm_def+'The fixed knots `kL`, `kM` and `kH` switch on `Max(y-kL,0)`, `Max(y-kM,0)` and `Max(y-kH,0)`. These continuous hinges alter feedback slopes in different state regions. Multiplication by the normalized input `((x1-uc)/us)` lets these slope changes depend on `x1`. Quadratic input terms allow curved forcing. Each fitted coefficient multiplies the basis term given in its description.',
 'origin':'After smooth polynomial fits, state-range residuals motivated an alternative local slope representation. The hinge operators and knots were a hand-chosen hypothesis, based on the observed training range; the derivative fitting and simulation comparisons evaluated it. Input-only hinges were also tested and were weaker. No automated knot search was used. This piecewise family supplies an alternative to global polynomial curvature.',
 'stage':'Ordinary least squares on every derivative row in data/train.csv using numpy.linalg.lstsq estimated all thirteen basis coefficients together. No starting values are needed for this linear solve. Those estimates, stored in hinge_results.json under hinge_state.ols and reproduced by fit_hinges.py, form the numerical starting vector below.',
 'limits':'The knots are not identified physical thresholds. Feedback slopes can be noncontracting at some observed points, and the far-state linear extensions need not be valid. The derivative is continuous but its state slope is discontinuous at the knots.'}
num='p0 + p1*'+z+' + p2*'+u+' + p3*'+v+' + p4*'+z+'*'+u+' + p5*'+u+'**2 + p6*'+v+'**2 + p7*'+u+'*'+v
den='Max(1 + p8*'+z+' + p9*'+u+' + p10*'+v+',dmin)'
nt=['1',z,u,v,z+'*'+u,u+'**2',v+'**2',u+'*'+v]
cases['Pade']={'expression':'('+num+')/'+den,'descriptions':['Numerator coefficient of `'+t+'`.' for t in nt]+['Denominator coefficient of `'+t+'`; changes the effective rate and curvature.' for t in [z,u,v]],'fixed':normal+[('dmin',.25,'-','Dimensionless denominator floor chosen to remove poles; not optimized. It is a safeguard rather than a fitted physical saturation.')],
 'family':'Guarded multivariate rational regression (a Padé-type numerator/denominator approximation, not a Taylor-matched Padé approximant). Reference for rational approximations: G. A. Baker Jr. and P. Graves-Morris, Padé Approximants, second edition, 1996; cited from memory, bibliographic source not checked.',
 'interpretation':common_def+norm_def+'The coefficients `p0` through `p7` control the numerator forcing and state-input interactions, as specified in their parameter descriptions. The coefficients `p8`, `p9` and `p10` modulate the denominator with normalized state and inputs, allowing curvature without higher-order numerator terms. The fixed dimensionless `dmin` prevents division by zero. No term is assigned a physical mechanism.',
 'origin':'Quadratic polynomial residuals and the improvement from inverse-state fits motivated testing rational curvature. A quadratic numerator and affine denominator were hand-chosen, then compared against polynomial and transformed-state models. A denominator floor was added as an explicit extrapolation safeguard, not learned from observations.',
 'stage':'All eleven coefficients were first estimated together on every derivative row of data/train.csv by scipy.optimize.least_squares with method trf, linear least-squares loss, two-point numerical derivative Jacobian, x_scale=jac, max_nfev=500 and ftol=xtol=gtol=1e-9. The training fit began at [0,-0.015,0.012,0.008,0.006,0.002,0.001,0,0.1,0,0], with bounds [-1,1] on numerator coefficients and [-0.25,0.25] on denominator coefficients; the wide numerator bounds exclude explosive iterates and the denominator bounds discourage extreme curvature. fit_nonlinear.py reproduces that fit. The derivative solution in nonlinear_results.json under rational_all.derivative supplies the numerical starting vector below. The final floor is part of fit_final.py.',
 'limits':'The floor removes a numerical pole but cannot justify the extrapolated response. The denominator state coefficient reaches its upper bound, indicating that this particular curvature constraint is active. Despite negative observed state slopes, stability over arbitrary inputs is unproved.'}
g='log(Max(y-p7,logfloor)/yref)'
terms=['1',g,u,v,g+'*'+u,u+'**2',v+'**2']
cases['LogShift']={'expression':' + '.join('p%d*%s'%(i,t) for i,t in enumerate(terms)), 'descriptions':['Coefficient of `'+t+'`.' for t in terms]+['Fitted state offset inside `log(Max(y-p7,logfloor)/yref)`, controls state-feedback curvature.'], 'fixed':[q for q in normal if q[0] not in ['yc','ys']]+[('logfloor',.02,'unknown','State-gap floor fixed below the observed fitted state gap to make the logarithm defined; not response-fitted.'),('yref',1.,'unknown','Reference state scale fixed to one raw state unit to make the logarithm argument dimensionless; not response-fitted.')],
 'family':'Shifted-logarithmic nonlinear state-feedback regression with quadratic input response. This is an empirical transformed-state family, not a claimed physical law. Prediction-error identification reference: L. Ljung, System Identification: Theory for the User, second edition, 1999; cited from memory, bibliographic source not checked.',
 'interpretation':common_def+'The fixed parameters `uc`, `us`, `vc` and `vs` normalize the inputs. The fitted parameter `p7` shifts the state before the logarithm; the fixed `logfloor` bounds the state gap and `yref` supplies its reference scale. The term `p1*log(Max(y-p7,logfloor)/yref)` gives nonlinear feedback that changes most rapidly near the offset. Its interaction with `((x1-uc)/us)` changes feedback with `x1`. The remaining coefficients control drift and linear or quadratic input forcing.',
 'origin':'Inverse and logarithmic state transforms improved the restricted polynomial baseline. A free logarithmic offset was a hand-chosen curvature hypothesis, tested against shifted inverse and square-root transforms. The shifted-log model was retained as a compact alternative. The state-gap floor was added to avoid an undefined logarithm below the fitted domain; it is not evidence of saturation.',
 'stage':'All eight parameters were first estimated together on all derivative rows in data/train.csv by scipy.optimize.least_squares, method trf, linear loss, two-point numerical derivative Jacobian, x_scale=jac, max_nfev=500 and ftol=xtol=gtol=1e-9. The derivative fit started at [0,-0.05,0,0.007,0.025,0,0.001,0.5]. Coefficients were bounded in [-5,5] and the offset in [-5,0.97], below the smallest observed state, to avoid a logarithmic pole. fit_more.py reproduces this fit; the more_results.json shift_log.derivative values are the numerical starting vector below. The final floored expression is fitted by fit_final.py.',
 'limits':'The offset is a shape parameter, not a physical zero. The floor defines a mathematical continuation only. Below that floor feedback curvature is lost; outside the observed input region feedback can change sign. Unknown units prevent assigning a physical meaning to the logarithm.'}
cases['Sigmoid']={'expression':'p0 + p1*(x2/vscale) + p2*(x2/vscale)**2 - (p3 + p4/(1+exp(p5*(x1/uscale-p6))))*(y-p7)', 'descriptions':['Constant drift in `dy`.','Linear input forcing coefficient of `(x2/vscale)`.','Quadratic input forcing coefficient of `(x2/vscale)**2`.','Positive lower asymptote of the relaxation rate.','Positive amplitude of the sigmoid relaxation-rate variation.','Dimensionless sigmoid steepness in normalized input.','Dimensionless sigmoid transition location in normalized input.','Reference state for relaxation, estimated jointly with forcing.'], 'fixed':[('vscale',18.,'unknown','Input scale fixed from the convenient training-data scale used in exploratory fits; not response-fitted.'),('uscale',60.,'unknown','Input scale fixed from the convenient training-data scale used in exploratory fits; not response-fitted.')],
 'family':'Input-scheduled first-order relaxation model with a logistic rate (a scalar quasi-linear-parameter-varying state equation). The logistic function is used as a mathematical saturation, not as a system-specific physical law. Prediction-error identification reference: L. Ljung, System Identification: Theory for the User, second edition, 1999; cited from memory, bibliographic source not checked.',
 'interpretation':common_def+'The fixed scales `uscale` and `vscale` normalize inputs. The coefficients `p0`, `p1` and `p2` provide constant, linear and quadratic forcing. The positive parameters `p3` and `p4` bound the damping rate, while dimensionless `p5` and `p6` set its steepness and transition location. The reference state `p7` sets the relaxation origin. For any real `x1`, the exact relaxation term has negative state slope because both rate coefficients are positive.',
 'origin':'The bilinear fit indicated damping varying strongly with `x1`. Exponential, polynomial, positive quadratic, and sigmoid rate schedules were explicitly compared. The sigmoid schedule was hand-chosen to preserve positive damping rather than allowing a linear-rate zero crossing. It is less accurate locally than the cubic but offers a deliberately conservative structural alternative.',
 'stage':'All eight fitted parameters were first estimated together on all derivative rows of data/train.csv by scipy.optimize.least_squares with method trf, linear loss, two-point numerical derivative Jacobian, x_scale=jac, max_nfev=500 and ftol=xtol=gtol=1e-9. Initial vector [0,0.006,0.008,0.01,0.3,3,1,1] represents a small positive relaxation rate and moderate input forcing, not prior physical knowledge. Bounds are the same as the final numerical vectors below; positivity of damping is required and other broad bounds avoid degenerate iterates. fit_nonlinear.py reproduces the derivative fit; nonlinear_results.json sigmoid_rate.derivative supplies the numerical starting vector below.',
 'limits':'Only an input-dependent linear state relaxation is available, so complex state curvature and hidden dynamics cannot be represented. The lower rate `p3` reaches its lower bound. The model is less accurate on the supplied trajectories but keeps a negative state slope; this does not guarantee RK4 stability for arbitrary step sizes or inputs.'}
for name,c in cases.items():
 r=R[name];pars=[]
 for i,(val,desc) in enumerate(zip(r['parameters'],c['descriptions'])):
  unit='unknown'
  if name=='Sigmoid':
   if i in [3,4]:unit='1/s'
   if i in [5,6]:unit='-'
  if name=='Pade' and i>=8:unit='-'
  pars.append(dict(name='p'+str(i),value=val,unit=unit,type='fitted',description=desc+' Estimated jointly in the final simulation-error fit; not fixed from another candidate.'))
 pars += [fixed(*q) for q in c['fixed']]
 method=c['stage']+' Final step: all fitted parameters, including shape parameters, were estimated together by bounded nonlinear least squares (scipy.optimize.least_squares, default method trf, loss linear). Analytical state and parameter partial derivatives were generated with sympy.lambdify; RK4 sensitivity recurrences supply the trajectory Jacobian. This is used rather than derivative-only fitting because the evaluation is a free-running state simulation. Starting values, in parameter-table order, are `'+repr(r['start'])+'`, with the heterogeneous units given in the parameter table. Lower and upper bound vectors are `'+repr(r['bounds'][0])+'` and `'+repr(r['bounds'][1])+'` in those same units. The broad coefficient bounds prevent explosive iterates; shape bounds preserve the chosen family. Settings: `max_nfev = 150`, `ftol = 1e-10`, `xtol = 1e-10`, `gtol = 1e-10`, `x_scale = "jac"`. The method is deterministic and uses no random seed. scipy.optimize.least_squares API documentation, SciPy v1.18.0 manual, was checked online for the trust-region reflective method; actual installed SciPy is 1.18.1. A local optimum, not a global guarantee, is obtained. fit_final.py writes all final values; make_submission.py formats the candidate.'
 criterion='Minimize the sum of squared free-running simulated-minus-observed `y` errors on both supplied trajectories, excluding each initial sample. Classical RK4 uses a step of 5 s and constant logged inputs per step, with no replacement of simulated states by later observations. This matches the scored variable and integration convention; equal row weights are used because no measurement variances are supplied. The derivative training fit supplies initialization, not the final criterion.'
 data='Initialization: all 1452 rows in data/train.csv, one trajectory, using `dy` as target. Structural checks use all 1454 rows of the separate data/val.csv trajectory. Final coefficient fit uses both files, retaining their separate initial conditions: 1451 and 1453 post-initial `y` residuals, respectively. No rows are arbitrarily discarded; the first state of each file is an initial condition, and the last input does not drive a scored subsequent sample. Validation is therefore used for selection and final estimation, not claimed as an independent final test.'
 met=r['metrics'];lim=c['limits']+' Residuals remain temporally structured: in the final fit the validation derivative-residual lag-one correlation is `'+format(met['val']['dy_residual_lag1'],'.3f')+'` and its correlation with the next `x2` increment is `'+format(met['val']['dy_residual_next_x2_change_correlation'],'.3f')+'` (both dimensionless, computed on data/val.csv). That increment is diagnostic only, never a model argument. This may reflect omitted dynamics or timing; causation cannot be determined. Final refit RMSE on data/train.csv is `'+format(met['train']['y_RMSE'],'.6f')+'` and on data/val.csv is `'+format(met['val']['y_RMSE'],'.6f')+'`, in the unspecified units of `y`; these are in-sample after refitting. No test performance is known. The observed combined envelope is approximately `0.992 <= y <= 2.187`, `1.628 <= x1 <= 94.449`, and `0.083 <= x2 <= 30.797`, all in their respective unspecified units; independently combining those extrema is not necessarily supported by either trajectory.'
 model=dict(expressions={'dy':c['expression']},parameters=pars,estimation=dict(criterion=criterion,data=data,method=method,script='fit_final.py'),discussion=dict(family=c['family'],interpretation=c['interpretation'],origin=c['origin'],limitations=lim))
 json.dump(model,open('models/'+name+'.json','w'),indent=2,ensure_ascii=True)
order=['Cubic','Hinge','Pade','LogShift','Sigmoid']
json.dump({'order':order,'recommended':'Cubic','reason':'The cubic polynomial had the lowest training-only derivative-initialized validation simulation RMSE among the retained smooth families: approximately 0.036525 in the unspecified units of `y`, computed on data/val.csv with constant-input 5 s RK4. The final joint simulation-error refit also has the lowest joint state error (training RMSE 0.023325; validation RMSE 0.033375, now in-sample, in the unspecified units of `y`). Its negative highest pure-state cubic term provides better far-state behavior than unconstrained quadratic growth, but neither global RK4 stability nor test accuracy is claimed. The pool includes piecewise, guarded rational, logarithmic and positive-rate alternatives because residual timing structure remains unexplained.'},open('models/pool.json','w'),indent=2)
print('Wrote',len(order),'candidate models.')
